mapper.update:
UPDATE permission
name = #{name}, code = #{code}, url = #{url}, type = #{type}, parent_id = #{parentId}, sort = #{sort}, icon = #{icon}, status = #{status},
WHERE id = #{id}

mapper.select:
SELECT * FROM permission WHERE status = 1
AND type = #{type}
ORDER BY sort ASC

choose.when:
SELECT DISTINCT p.* FROM permission p INNER JOIN role_permission rp ON p.id = rp.permission_id WHERE rp.role_id IN
#{roleId}
AND p.status = 1 ORDER BY p.sort ASC
